def maximize_sum_matrix(n):
    # Create a square matrix of size n x n with all entries as -1
    matrix = np.full((n, n), -1, dtype=int)

    # Zeros are not near an odd number of ones
    for i in product(range(n), repeat=2):
        if matrix[i[0] % 2, i[1] % 2] != 0:
            matrix[i[0] % 2, i[1] % 2] = 0

    # Compute the sum of all products if all entries are positive
    return np.prod(np.unique(matrix, return_counts=True)[0])
