MOD = 10**9 + 7

def find_minai(a):
    return sum(ai - 1 for ai in sorted(a) if ai)

def find_maxai(a):
    return sum(ai - 1 for ai in sorted(a, reverse=True) if ai)

def n_ways(n, ai, memo={}):
    if n == 0:
        return 1
    if n in memo:
        return memo[n]

    max_a = find_maxai(ai)
    min_a = find_minai(ai)

    memo[n] = 0

    for slot_a in range(min_a, max_a + 1):
        if slot_a <= min_a:
            # faster faster faster faster faster !!!!
            memo[n] = (memo[n] + n_ways((n-1)*2, (ai[0:n-1]+slot_a)*2+slot_a, memo)) % MOD
        else:
            # faster slower faster faster faster !!!!
            memo[n] = (memo[n] + (n-1)**2 * n_ways((n-1), (ai[0:n-1]+slot_a+1)*2, memo)) % MOD

    return memo[n]

