def mod_inverse(a, m):
    """Calculate the modular inverse of a under modulo m."""
    b = m
    x = 0
    y = 1
    while a > 1:
        q = a // b
        t = b
        b = a % b
        a = t
        t = x
        x = y - q * x
        y = t
    if x < 0:
        x += m
    return x % m

def modular_exponentiation(a, b, m):
    """Calculate (a^b) % m using the square-and-multiply algorithm."""
    result = 1
    base = a % m
    while b > 0:
        if b & 1:
            result = (result * base) % m
        base = (base * base) % m
        b >>= 1
    return result % m

