def split_permutation(n):
    """Splits a permutation into the minimum number of monotonic subsequences."""
    increasing_permutations = []
    decreasing_permutations = []
    for i in range(n):
        inc_subseq = True if i % 2 == 0 else False
        curr_subset = [i]
        for j in range(1, n):
            if j % 2 == 0 and i + j < n and not inc_subseq:
                curr_subset.append(j)
                if j + 1 < n and j % 2 == 1 and not incr:
                    incr = True
            elif j % 2 != 0 and i + j < n and inc_subseq:
                if j + 1 < n and j % 2 == 0 and incr:
                    incr = True
                else:
                    incr = False
        if incr:
            increasing_permutations.append(curr_subset)
        else:
