def count_beautiful_permutations(n, k):
    if k > n // 2:
        return 0
    mod = 10**9 + 7
    if k == 0 or k == 1:
        return 1
    if k == n:
        return n + 1

    dp = [0] * (k + 1)

    for i in range(n, 0, -1):
        dp[k + 1], dp[k], _ = db_helper(k, dp, i, n)

    return dp[k] % mod

def db_helper(cur_k, dp, i_pos, n):
    ans = 0
    visited = set()

    for next_k in range(k - 1, 0, -1):
        if cur_k - next_k >= n and next_k - n >= k:
            ans += sum(dp[:next_k] >= i_pos)
            dp[next_k] = dp[i_pos]
            continue

        dp[next_k], rec_count = db_helper(next_k, dp, i_pos, n)
        ans += (n - rec_count) * dfs(dp[next_k], i_pos + 1, visited)

    if dp[next_k] == 0:
        visited.add(dp[next_k])
        dp[next_k], answer = db_helper(cur_k - n, dp, i_pos + n + 1, n)
        answer += (n - visited) * dfs(dp[next_k], i_pos + n + 1, visited)
        dp[next_k] = answer

    return dp[next_k], answer

def dfs(carry_dp, pos, visited):
    if pos == length:
        return carry_dp == i_pos
    if carry_dp == i_pos:
        return dfs(carry_dp + 1, pos + 1, visited)

    cnt = 0
    for other_k in range(length):
        if dp[other_k] == i_pos and other_k not in visited:
            cnt += dfs(carry_dp | other_k, pos + 1, visited)
            cnt %= mod

    return cnt

