        attacker_point = 0
        opponent_number = len(sequence) + len(strengths_defense)

        for i, defender in enumerate(sequence):
            if defender < strengths_offense[i]:
                defender_point += 1
            elif defender == strengths_offense[i]:
                defender_point += 0.5
            else:
                attacker_point += 1

        win_condition = defender_point >= len(strengths_defense)
        return win_condition, len(sequences[0]) == attacker_point + len(strengths_defense)

    sequences = sorted(zip(strengths_defense, strengths_offense[:len(strengths_defense)]), reverse=True)
    results = []

    for _ in range(T):
        N, M = [int(x) for x in input().split()]
        opponents = list(map(int, input().split()))
        team_strengths = list(map(int, input().split()))

        survivor_queue = []
        for strength_offset in opponents:
