            for team_strength_offset in team_strengths:
                if team_strength_offset >= strength_offset:
                    temp_list.append(team_strength_offset)
            survivor_queue.append(temp_list)

        for _ in range(N):
            sequence = zip(*sorted(zip(*survivor_queue), key=lambda x: x[0])[::-1])
            winner, defender_eliminated = check(sequence)
            if not defender_eliminated:
                return 'NO'

            sequences[sequence[-1][::-1]] = []
            sequences[-1] = sequence

        T1 = len(list(filter(lambda x: x is not [], sequences[0])))
        assert T1 + M < 1_000_000_000
        results.append(['YES'] * T1)

    return results


