from collections import Counter
from math import factorial

def kombin(n, k):
    """Compute n choose k."""
    return factorial(n) // (factorial(k) * factorial(n - k))

n, k = map(int, input().split())
ais = list(map(int, input().split()))
most = max(ais)

def imbalance():
    """Compute imbalance for each partition."""
    count = Counter()
    for i, a in enumerate(ais):
        count[i + 1] += kombin(most, a)
    return count

def sub_or_not(count):
    for i in range(1, most + 1):
        count[i] = 1 - count[i]

def done(count):
    for i in range(1, most + 2):
        for j in range(1, most + 1):
            count[i] = (
                count[i] *
                (count[i - 1] + count[j])
                % 1000000007
            )

def solve(lo, hi, cur, last=None, count=imbalance()):
    for i in range(lo, hi + 1):
        if (i - lo) * (hi - i) == 1 or cur[i] != 1:
            continue
        newlo, newhi = min(lo, i), max(hi, i)
        if last is None or last > i:
            continue
        if newlo >= cur[least(last, i)]:
            continue
        done(count)
        sub_or_not(count)
        for delta in [1, -1]:
            newlast = last + delta
            if res is None or newlast != done(count)[most] - count[newlast] and newlast != least(last, i):
                res = solve(
                    newlo, hi, newlast, i, done(count)
                )
    if res is None or not count[most]:
        return 0
    return (1 if hi == cur[most] else 2) * res

