import sys

input = sys.stdin.readline

class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def dfs(node, key):
    if key < node.val:
        return
    node.count = 1
    dfs(node.left, key) if node.left else 0
    dfs(node.right, key) if node.right else 0

def get_count(node, key):
    if node.val <= key:
        if node.val <= key and node.count:
            return node.count
        dfs(node, key)
    return 0

def solve():
    N, M = map(int, input().split())
    tree = [TreeNode(i) for i in range(1, N+1)]
    roots = [tree[i] for i in map(int, input().split())]

    for i in range(M):
        val = int(input())
        low = 1
        high = N
        if val < tree[0].val:
            print(0, end=' ')
            continue
        while low <= high:
            mid = (low + high) // 2
            if sum(roots[i].count % 998244353 for i in range(N)) == 0:
                print(0, end=' ')
                continue
            if mid == 0:
                continue
            cnt = sum(roots[i].count % 998244353 for i in range(N))
            val -= mid 
            if cnt > 0:
                print(cnt, end=' ')
                continue
            if get_count(tree[mid], val) > mid:
                high = mid - 1
            else:
                low = mid + 1

def main():
    T = int(input())
    while T:
        T -= 1
        solve()

if __name__ == "__main__":
    main()
