from collections import defaultdict

def count_paintings(n, m, k):
    mod = 1000000007
    dp = defaultdict(int)
    dp[(0, 0)] = 1

    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue  # Skip the origin position
            elif i > 0:
                dp[(i, j)] += dp[(i-1, j)] % mod
            elif j > 0:
                dp[(i, j)] += dp[(i, j-1)] % mod

    total_paintings = dp[(n-1, m-1)] % mod * k % mod
    return total_paintings

# Example usage
n, m, k = map(int, input().split())
print(count_paintings(n, m, k))
